css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.transport-widget {
  --title-color: #0E5B67;
  --subtitle-color: #728DA5;
  --text-color: #246975;
  --border-color: #4B83A7;
  --separator-color: #C8DAE5;
  --mechanical-color: #4E4E4E;
  --mechanical-fill: #D7D8DB;

  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
  color: var(--text-color);

  user-select: none;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.transport-stage {
  position: absolute;
  top: 0;
  left: 0;
  width: 1610px;
  height: 755px;

  transform-origin: top left;
  background: transparent;
}

.screen-header {
  position: absolute;
  top: 14px;
  left: 30px;
  right: 30px;
  height: 56px;

  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}

.screen-heading {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.screen-title {
  color: var(--title-color);
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  white-space: nowrap;
}

.screen-subtitle {
  color: var(--subtitle-color);
  font-size: 14px;
  line-height: 1.3;
  white-space: nowrap;
}

.screen-subtitle[hidden] {
  display: none;
}

.screen-reference {
  margin-top: 3px;
  padding: 6px 12px;

  border: 1px solid var(--separator-color);
  border-radius: 4px;

  color: #526D80;
  font-size: 13px;
  font-weight: 700;
  line-height: 18px;
}

.travel-message {
  position: absolute;
  top: 80px;
  left: 30px;
  width: 850px;
  height: 50px;

  display: flex;
  align-items: center;
  padding: 0 18px;

  border: 1px solid var(--border-color);
  border-radius: 5px;
  background: #E4F0FA;

  color: #176A95;
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

.readings-panel {
  position: absolute;
  top: 146px;
  left: 30px;
  width: 345px;
  height: 106px;

  display: grid;
  grid-template-rows: repeat(2, 38px);
  align-content: center;
  gap: 10px;
  padding: 9px 14px;

  border: 1px solid var(--separator-color);
  border-radius: 5px;
  background: transparent;
}

.reading-row {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr) 28px;
  align-items: center;
  gap: 10px;
}

.reading-label {
  color: var(--title-color);
  font-size: 18px;
  font-weight: 700;
}

.empty-reading {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 38px;
  padding: 0 6px;

  border: 1px solid var(--border-color);
  border-radius: 3px;
  background: #F7FBFD;

  color: #1C5A6B;
  font-size: 18px;
  font-weight: 700;
  line-height: 1;
  text-align: center;
  white-space: nowrap;
}

#current-position {
  display: block;
  line-height: 1;
}

.reading-unit {
  color: var(--subtitle-color);
  font-size: 16px;
}

.process-diagram {
  position: absolute;
  top: 148px;
  left: 30px;
  width: 1550px;
  height: 519px;

  overflow: hidden;
  font-family: Arial, Helvetica, sans-serif;
}

.mechanical-line {
  fill: none;
  stroke: var(--mechanical-color);
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.axis-line {
  fill: none;
  stroke: #71808A;
  stroke-width: 1.2;
  stroke-dasharray: 14 7 3 7;
}

.shaft-body {
  fill: #E3E7EA;
  stroke: var(--mechanical-color);
  stroke-width: 1.5;
}

.machine-body {
  fill: var(--mechanical-fill);
  stroke: var(--mechanical-color);
  stroke-width: 1.5;
}

.machine-inset {
  fill: #EEF1F3;
  stroke: var(--mechanical-color);
  stroke-width: 1.3;
}

.motor-circle {
  fill: #FFFFFF;
  stroke: var(--mechanical-color);
  stroke-width: 1.3;
}

.motor-letter {
  fill: var(--mechanical-color);
  font-size: 12px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

.motor-tag {
  fill: #405B6B;
  font-size: 11px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

.sensor-body {
  fill: #FFFFFF;
  stroke: var(--mechanical-color);
  stroke-width: 1.2;
}

.sensor-detail {
  fill: none;
  stroke: var(--mechanical-color);
  stroke-width: 3;
}

.sensor-tag {
  fill: #536F81;
  font-size: 12px;
  font-weight: 700;
  text-anchor: middle;
}

.equipment-envelope {
  fill: none;
  stroke: #82919B;
  stroke-width: 1.3;
  stroke-dasharray: 12 7;
}

.equipment-title {
  fill: var(--title-color);
  font-size: 20px;
  font-weight: 700;
  text-anchor: middle;
}

.position-marker {
  fill: #947348;
  stroke: #685137;
  stroke-width: 1.8;
  visibility: hidden;
}

.position-marker.is-visible {
  visibility: visible;
}

.position-box {
  fill: #FFF1BF;
  stroke: #C7AE66;
  stroke-width: 1.2;
}

.position-text {
  fill: #756023;
  font-size: 18px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

.station-panel {
  fill: transparent;
  stroke: var(--separator-color);
  stroke-width: 1.2;
}

.folder-title {
  fill: var(--title-color);
  font-size: 18px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

.deposit-label {
  fill: var(--text-color);
  font-size: 16px;
  font-weight: 700;
  text-anchor: start;
  dominant-baseline: middle;
}

.numeric-slot {
  fill: #F7FBFD;
  stroke: var(--border-color);
  stroke-width: 1.1;
}

.foundation-hatch {
  fill: none;
  stroke: #82919B;
  stroke-width: 1;
}

.foundation-fill {
  fill: url(#transport-hatch);
  stroke: none;
}

.timer-label {
  fill: var(--text-color);
  font-size: 16px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

.timer-separator {
  fill: var(--subtitle-color);
  font-size: 21px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

.screen-footer {
  position: absolute;
  top: 685px;
  left: 30px;
  right: 30px;
  height: 56px;

  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;

  border-top: 1px solid var(--separator-color);
}

.navigation-left,
.navigation-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.visual-button {
  display: flex;
  align-items: center;
  justify-content: center;

  height: 40px;
  padding: 0 18px;

  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: linear-gradient(180deg, #FFFFFF, #EEF5F8);

  color: #1C5A6B;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;

  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.visual-button--primary {
  border-color: var(--title-color);
  background: var(--title-color);
  color: #FFFFFF;
  box-shadow: none;
}

.brand-label {
  margin-right: 12px;
  color: #009999;
  font-size: 23px;
  font-weight: 700;
  letter-spacing: 1px;
}

