"use strict";

(function () {
  const SVG_NS = "http://www.w3.org/2000/svg";

  const BASE_WIDTH = 1610;
  const BASE_HEIGHT = 755;

  const DEFAULT_TITLE =
    "LÍNEA 3 / TRANSPORTE Y PLEGADO";

  const DEFAULT_SUBTITLE =
    "Vista general del carro transportador, depositadores y prensa";

  const POSITION_ALIAS = "var1";

  const DESTINATIONS = [
    "",
    "Depositador 1A",
    "Depositador 1B",
    "Depositador 2A",
    "Depositador 2B",
    "Depositador 3A",
    "Depositador 3B",
    "Depositador 4A",
    "Depositador 4B",
    "Prensa"
  ];

  const POSITION_NAMES = [
    "",
    "1A", "1B",
    "2A", "2B",
    "3A", "3B",
    "4A", "4B"
  ];

  const STATION_CENTERS = [165, 485, 805, 1125];
  const COLUMN_OFFSET = 36;

  const POSITION_CENTERS = STATION_CENTERS.flatMap(
    function (center) {
      return [
        center - COLUMN_OFFSET,
        center + COLUMN_OFFSET
      ];
    }
  );

  const MOTORS = [
    { tag: "M482", position: 4 },
    { tag: "M502", position: 5 },
    { tag: "M522", position: 6 },
    { tag: "M542", position: 7 },
    { tag: "M562", position: 8 }
  ];

  let root = null;
  let stage = null;
  let messageElement = null;
  let currentPositionElement = null;

  let latestWidget = null;
  let resizeObserver = null;
  let initialized = false;
  let currentName = null;

  const positionTexts = [];
  const positionMarkers = [];
  const depositRows = [];

  function svgElement(tag, attributes, parent, text) {
    const element = document.createElementNS(SVG_NS, tag);

    Object.keys(attributes || {}).forEach(function (key) {
      element.setAttribute(key, String(attributes[key]));
    });

    if (text !== undefined) {
      element.textContent = text;
    }

    if (parent) {
      parent.appendChild(element);
    }

    return element;
  }

  function addUse(parent, symbol, x, y, width, height) {
    return svgElement(
      "use",
      {
        href: "#" + symbol,
        x: x,
        y: y,
        width: width,
        height: height
      },
      parent
    );
  }

  function addNumericSlot(parent, x, y, width, height) {
    return svgElement(
      "rect",
      {
        class: "numeric-slot",
        x: x,
        y: y,
        width: width,
        height: height,
        rx: 3
      },
      parent
    );
  }

  /*
   * Conserva el borde derecho original: center + 110.
   * El conjunto texto + separación + cuadro ocupa una franja
   * centrada de 220 px dentro del plegador.
   */
  function addDepositRow(parent, center, text, top) {
    const label = svgElement(
      "text",
      {
        class: "deposit-label",
        x: center - 110,
        y: top + 12.5
      },
      parent,
      text
    );

    const slot = addNumericSlot(
      parent,
      center + 22,
      top,
      88,
      25
    );

    depositRows.push({
      center: center,
      label: label,
      slot: slot
    });
  }

  function fitDepositRows() {
    depositRows.forEach(function (row) {
      const left = row.center - 110;
      const right = row.center + 110;
      const gap = 20;

      /*
       * Se mide el texto real para respetar los 20 px.
       * Se ajusta su inicio para centrar el conjunto completo.
       */
      row.label.setAttribute("x", String(left));

      const initialBounds = row.label.getBBox();

      if (initialBounds.width <= 0) return;

      const correction = left - initialBounds.x;
      row.label.setAttribute("x", String(left + correction));

      const bounds = row.label.getBBox();
      const slotLeft = bounds.x + bounds.width + gap;

      row.slot.setAttribute("x", String(slotLeft));
      row.slot.setAttribute("width", String(right - slotLeft));
    });
  }

  function addSensor(parent, tag, x, y, labelBelow) {
    const group = svgElement("g", {}, parent);

    addUse(group, "transport-sensor", x, y, 32, 32);

    svgElement(
      "text",
      {
        class: "sensor-tag",
        x: x + 16,
        y: labelBelow ? y + 45 : y - 6
      },
      group,
      tag
    );
  }

  function addMotor(parent, tag, centerX) {
    const group = svgElement("g", {}, parent);
    const top = 20;

    addUse(
      group,
      "transport-motor",
      centerX - 24,
      top,
      48,
      90
    );

    svgElement(
      "text",
      {
        class: "motor-tag",
        x: centerX,
        y: top + 23
      },
      group,
      tag
    );

    svgElement(
      "path",
      {
        class: "mechanical-line",
        d:
          "M" + (centerX - 7) + " " + (top + 87) +
          "V126H" + (centerX + 7) +
          "V" + (top + 87)
      },
      group
    );

    svgElement(
      "path",
      {
        class: "axis-line",
        d: "M" + centerX + " " + (top + 87) + "V136"
      },
      group
    );
  }

  function buildAlignmentAxes() {
    const parent = document.getElementById("alignment-axes");
    parent.replaceChildren();

    POSITION_CENTERS.forEach(function (centerX, index) {
      const hasMotor = MOTORS.some(function (motor) {
        return motor.position === index + 1;
      });

      svgElement(
        "path",
        {
          class: "axis-line",
          d:
            "M" + centerX + " " + (hasMotor ? 12 : 118) +
            "V429"
        },
        parent
      );
    });

    svgElement(
      "path",
      {
        class: "axis-line",
        d: "M16 347H1272"
      },
      parent
    );

    svgElement(
      "path",
      {
        class: "axis-line",
        d: "M1415 98V245"
      },
      parent
    );
  }

  function buildEquipment() {
    const parent = document.getElementById("fixed-equipment");
    parent.replaceChildren();

    MOTORS.forEach(function (motor) {
      addMotor(
        parent,
        motor.tag,
        POSITION_CENTERS[motor.position - 1]
      );
    });

    const motor482 = POSITION_CENTERS[3];
    const motor502 = POSITION_CENTERS[4];
    const motor522 = POSITION_CENTERS[5];
    const motor542 = POSITION_CENTERS[6];
    const motor562 = POSITION_CENTERS[7];

    addSensor(parent, "-B601", motor482 - 70, 76, false);
    addSensor(parent, "-B602", motor502 - 70, 83, false);
    addSensor(parent, "-B603", motor522 + 38, 83, false);

    addSensor(parent, "-B604", motor542 - 76, 22, false);
    addSensor(parent, "-B605", motor542 - 76, 86, false);

    addSensor(parent, "-B606", motor562 + 44, 22, false);
    addSensor(parent, "-B607", motor562 + 44, 86, false);

    // Símbolo debajo del eje, texto arriba del símbolo.
    addSensor(parent, "-B721", 14, 218, false);

    addSensor(parent, "-B722", 1284, 218, true);
  }

  function buildMarkers() {
    const parent = document.getElementById("position-markers");
    parent.replaceChildren();
    positionMarkers.length = 0;

    POSITION_CENTERS.forEach(function (centerX, index) {
      const marker = svgElement(
        "rect",
        {
          class: "position-marker",
          x: centerX - 23,
          y: 126,
          width: 46,
          height: 76,
          rx: 2,
          "data-position": index + 1,
          "aria-hidden": "true"
        },
        parent
      );

      positionMarkers.push(marker);
    });
  }

  function addFourthFoundation(parent, center) {
    svgElement(
      "rect",
      {
        class: "foundation-fill",
        x: center - 120,
        y: 402,
        width: 240,
        height: 11
      },
      parent
    );

    svgElement(
      "path",
      {
        class: "mechanical-line",
        d:
          "M" + (center - 120) + " 402" +
          "H" + (center - 94) +
          "V418H" + (center + 94) +
          "V402H" + (center + 120)
      },
      parent
    );

    svgElement(
      "rect",
      {
        class: "foundation-fill",
        x: center - 94,
        y: 418,
        width: 188,
        height: 8
      },
      parent
    );
  }

  function buildStations() {
    const parent = document.getElementById("folder-stations");
    parent.replaceChildren();

    positionTexts.length = 0;
    depositRows.length = 0;

    STATION_CENTERS.forEach(function (center, index) {
      const number = index + 1;
      const group = svgElement("g", {}, parent);

      svgElement(
        "rect",
        {
          class: "position-box",
          x: center - 106,
          y: 213,
          width: 212,
          height: 32,
          rx: 4
        },
        group
      );

      const positionText = svgElement(
        "text",
        {
          class: "position-text",
          x: center,
          y: 229
        },
        group,
        "No signal"
      );

      positionTexts.push(positionText);

      svgElement(
        "rect",
        {
          class: "station-panel",
          x: center - 147,
          y: 255,
          width: 294,
          height: 260,
          rx: 6
        },
        group
      );

      if (index === 3) {
        addFourthFoundation(group, center);
      }

      addUse(
        group,
        "transport-folder",
        center - 120,
        265,
        240,
        164
      );

      svgElement(
        "text",
        {
          class: "folder-title",
          x: center,
          y: 441
        },
        group,
        "Plegador " + String(number).padStart(2, "0")
      );

      addDepositRow(
        group,
        center,
        "Depos. " + number + "A",
        452
      );

      addDepositRow(
        group,
        center,
        "Depos. " + number + "B",
        484
      );
    });
  }

  function buildTimers() {
    const parent = document.getElementById("folder-timers");
    parent.replaceChildren();

    for (let index = 0; index < 4; index += 1) {
      const top = 270 + index * 60;

      svgElement(
        "text",
        {
          class: "timer-label",
          x: 1415,
          y: top
        },
        parent,
        "Plegador " + String(index + 1).padStart(2, "0")
      );

      addNumericSlot(parent, 1354, top + 14, 50, 28);
      addNumericSlot(parent, 1426, top + 14, 50, 28);

      svgElement(
        "text",
        {
          class: "timer-separator",
          x: 1415,
          y: top + 28
        },
        parent,
        ":"
      );
    }
  }

  function hasOwn(object, key) {
    return Object.prototype.hasOwnProperty.call(object, key);
  }

  function readAdditionalValue(widget, alias) {
    const variables = widget && widget.vars;

    if (
      !variables ||
      typeof variables !== "object" ||
      Array.isArray(variables) ||
      !hasOwn(variables, alias)
    ) {
      return undefined;
    }

    const entry = variables[alias];

    if (
      entry !== null &&
      typeof entry === "object" &&
      hasOwn(entry, "value")
    ) {
      return entry.value;
    }

    return entry;
  }

  function asInteger(raw) {
    if (typeof raw !== "number" && typeof raw !== "string") {
      return null;
    }

    if (typeof raw === "string" && raw.trim() === "") {
      return null;
    }

    const number = Number(raw);

    return Number.isFinite(number) && Number.isInteger(number)
      ? number
      : null;
  }

  function updateProcess(widget) {
    if (!messageElement || !currentPositionElement) return;

    const mainValue = asInteger(
      widget ? widget.value : undefined
    );

    const position = asInteger(
      readAdditionalValue(widget, POSITION_ALIAS)
    );

    // Mensaje azul: variable principal.
    messageElement.textContent =
      mainValue !== null && mainValue >= 1 && mainValue <= 9
        ? "Carro Transport. Hacia " + DESTINATIONS[mainValue]
        : "No signal";

    // Cuadro blanco Posición: variable adicional var1.
    currentPositionElement.textContent =
      position !== null && position >= 1 && position <= 8
        ? POSITION_NAMES[position]
        : "No signal";

    // Cuatro casillas amarillas.
    positionTexts.forEach(function (element, index) {
      const positionA = index * 2 + 1;
      const positionB = index * 2 + 2;

      element.textContent =
        position === positionA || position === positionB
          ? "Posicion " + POSITION_NAMES[position]
          : "No signal";
    });

    // Rectángulo visible según var1.
    positionMarkers.forEach(function (marker, index) {
      const visible = position === index + 1;

      marker.classList.toggle("is-visible", visible);
      marker.setAttribute("aria-hidden", String(!visible));
    });
  }

  function fitHeader() {
    [
      [".screen-title", 28],
      [".screen-subtitle", 14]
    ].forEach(function (entry) {
      const element = stage.querySelector(entry[0]);

      if (!element || element.hidden) return;

      element.style.fontSize = entry[1] + "px";

      if (
        element.clientWidth > 0 &&
        element.scrollWidth > element.clientWidth
      ) {
        element.style.fontSize =
          (
            entry[1] *
            element.clientWidth /
            element.scrollWidth
          ) + "px";
      }
    });
  }

  function updateHeader(widget) {
    const name =
      widget && typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    if (name === currentName) return;
    currentName = name;

    const separator = name.indexOf("//");

    const titleText =
      separator < 0
        ? name
        : name.slice(0, separator).trim();

    const subtitleText =
      separator < 0
        ? DEFAULT_SUBTITLE
        : name.slice(separator + 2).trim();

    const title = stage.querySelector(".screen-title");
    const subtitle = stage.querySelector(".screen-subtitle");

    title.textContent = titleText || DEFAULT_TITLE;
    subtitle.textContent = subtitleText;
    subtitle.hidden = subtitleText === "";

    fitHeader();
  }

  function fitStage() {
    if (!root || !stage) return;

    const width = root.clientWidth;
    const height = root.clientHeight;

    if (width <= 0 || height <= 0) return;

    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT
    );

    stage.style.left =
      ((width - BASE_WIDTH * scale) / 2) + "px";

    stage.style.top =
      ((height - BASE_HEIGHT * scale) / 2) + "px";

    stage.style.transform = "scale(" + scale + ")";

    fitDepositRows();
  }

  function render(widget) {
    if (!initialized) return;

    updateHeader(widget);
    updateProcess(widget);
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    render(widget);
  };

  function initialize() {
    if (initialized) return;

    root = document.querySelector(".transport-widget");
    stage = document.querySelector(".transport-stage");
    messageElement = document.getElementById("travel-message");
    currentPositionElement =
      document.getElementById("current-position");

    if (
      !root ||
      !stage ||
      !messageElement ||
      !currentPositionElement
    ) {
      return;
    }

    buildAlignmentAxes();
    buildEquipment();
    buildMarkers();
    buildStations();
    buildTimers();

    initialized = true;

    render(latestWidget || window.WIDGET || null);
    fitStage();

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(fitStage);
      resizeObserver.observe(root);
    } else {
      window.addEventListener("resize", fitStage);
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(function () {
        fitHeader();
        fitStage();
      });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
